def between(text: str, start: str, end: str, replacement: str) -> str:
    a = text.find(start)
    if a < 0:
        raise RuntimeError(f'start marker not found: {start[:80]}')
    b = text.find(end, a)
    if b < 0:
        raise RuntimeError(f'end marker not found: {end[:80]}')
    return text[:a] + replacement.rstrip() + '\n' + text[b:]

helpers = r'''function percentPreset(label,customId){if(String(label).startsWith('Custom'))return n(customId);const m=String(label).match(/(\d+(?:\.\d+)?)%/);if(!m)throw new Error('No percentage found in selected preset');return parseFloat(m[1])/100}
function motorOcpdFactor(motorType,device,flc,lockedRotor,hp,dc=false){
  if(device.startsWith('Instantaneous-trip')){
    if(dc)return hp<=50?2.50:2.00;
    if(device.includes('locked-rotor')){if(!(lockedRotor>0))throw new Error('Enter locked-rotor current for the locked-rotor instantaneous-trip method');return (2.15*lockedRotor)/flc}
    return 13.00;
  }
  if(dc)return 1.50;
  const td=device.startsWith('Time-delay'),ntd=device.startsWith('Non-time-delay');
  if(motorType.startsWith('Wound-rotor'))return 1.50;
  if(motorType.includes('autotransformer')||motorType.includes('star-delta')){if(td)return 1.75;if(flc<=30)return ntd?2.50:2.00;return 2.00}
  if(td)return 1.75;if(ntd)return 3.00;return 2.50;
}
function welderDutyFactor(type,duty){
  if(type==='Resistance welder')return {'50%':.71,'40%':.63,'30%':.55,'25%':.50,'20%':.45,'15%':.39,'10%':.32,'7.5%':.27,'5%':.22}[duty]??(()=>{throw new Error('Select a resistance-welder duty cycle')})();
  return {'100%':1.00,'90%':.95,'80%':.89,'70%':.84,'60%':.78,'50%':.71,'40%':.63,'30%':.55,'20%':.45,'1 hour':.75}[duty]??(()=>{throw new Error('Select an arc-welder duty cycle')})();
}
function syncWelderDuty(){const t=s('w_type'),el=document.getElementById('w_duty');if(!el)return;const opts=t==='Resistance welder'?['50%','40%','30%','25%','20%','15%','10%','7.5%','5%']:['100%','90%','80%','70%','60%','50%','40%','30%','20%','1 hour'];el.innerHTML=opts.map(x=>`<option>${x}</option>`).join('');el.value=t==='Resistance welder'?'30%':'60%'}
'''
