old_init = "nav.innerHTML=sections.map(([id,num,name],j)=>`<button class=\"${j?'':'active'}\" onclick=\"showSection('${id}',this)\">${num} — ${name}</button>`).join('');main.innerHTML=sections.map(x=>html[x[0]]).join('');document.getElementById('s2').classList.add('active');function showSection(id,button){document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));button.classList.add('active');window.scrollTo({top:0,behavior:'smooth'})}"
new_init = "nav.innerHTML=sections.map(([id,num,name],j)=>`<button class=\"${j?'':'active'}\" onclick=\"showSection('${id}',this)\">${num} — ${name}</button>`).join('');main.innerHTML=sections.map(x=>html[x[0]]).join('');function showSection(id,button){document.querySelectorAll('.section').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));if(button)button.classList.add('active');window.scrollTo({top:0,behavior:'smooth'})}const requested=new URLSearchParams(location.search).get('section');const initial=sections.some(x=>x[0]===requested)?requested:'s2';const idx=sections.findIndex(x=>x[0]===initial);showSection(initial,document.querySelectorAll('.nav button')[idx]);"
